const uint8_t* oledFaceFrameData(OledFaceClipId id, uint8_t frameIdx) {
    switch (id) {
        case OledFaceClipId::IdleBlink:
            if (frameIdx >= 12) frameIdx = 0;
            return kOledFaceIdleBlinkFrames[frameIdx];
        case OledFaceClipId::LookLR:
            if (frameIdx >= 8) frameIdx = 0;
            return kOledFaceLookLRFrames[frameIdx];
        case OledFaceClipId::Alert:
            if (frameIdx >= 16) frameIdx = 0;
            return kOledFaceAlertFrames[frameIdx];
        case OledFaceClipId::Happy:
            if (frameIdx >= 20) frameIdx = 0;
            return kOledFaceHappyFrames[frameIdx];
        default:
            return kOledFaceIdleBlinkFrame0;
    }
}